package com.wizzadrds.theworldremembers.knowledge; import com.mojang.serialization.Codec; import com.mojang.serialization.codecs.RecordCodecBuilder; import net.minecraft.core.UUIDUtil; import java.util.UUID; public record KnowledgeFact(UUID knower, UUID subject, String eventType, UUID source, KnowledgeOrigin origin, int confidence, long observedTick, long lastUpdatedTick){ public KnowledgeFact{if(confidence<0||confidence>100)throw new IllegalArgumentException("confidence");} public static final Codec<KnowledgeFact> CODEC=RecordCodecBuilder.create(i->i.group(UUIDUtil.CODEC.fieldOf("knower").forGetter(KnowledgeFact::knower),UUIDUtil.CODEC.fieldOf("subject").forGetter(KnowledgeFact::subject),Codec.STRING.fieldOf("eventType").forGetter(KnowledgeFact::eventType),UUIDUtil.CODEC.fieldOf("source").forGetter(KnowledgeFact::source),Codec.STRING.xmap(KnowledgeOrigin::valueOf,KnowledgeOrigin::name).fieldOf("origin").forGetter(KnowledgeFact::origin),Codec.INT.fieldOf("confidence").forGetter(KnowledgeFact::confidence),Codec.LONG.fieldOf("observedTick").forGetter(KnowledgeFact::observedTick),Codec.LONG.fieldOf("lastUpdatedTick").forGetter(KnowledgeFact::lastUpdatedTick)).apply(i,KnowledgeFact::new)); public KnowledgeFact degrade(long tick){long elapsed=Math.max(0,tick-lastUpdatedTick);int loss=(int)Math.min(100,elapsed/1200);return new KnowledgeFact(knower,subject,eventType,source,origin,Math.max(0,confidence-loss),observedTick,tick);} }
